import React, { useState, useEffect } from "react";
import { Link, useLocation } from "react-router-dom";
import { menuItems } from "./menuConfig";
import { site } from "../../data/site";
import { scrollToHash } from "../../utils/scrollToHash";

const Header = () => {
  const location = useLocation();
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Works/About/AI/Contact are anchors on "/" now. If we're already on the
  // single page, smooth-scroll to the section instead of letting the Link
  // do a plain (unanimated) navigation.
  const handleNavClick = (e, href) => {
    if (location.pathname !== "/") return;
    const hashIndex = href.indexOf("#");
    if (hashIndex === -1) return;
    e.preventDefault();
    scrollToHash(href.slice(hashIndex));
  };

  const isActive = (href) => {
    const hashIndex = href.indexOf("#");
    if (hashIndex === -1) return location.pathname === href && !location.hash;
    return location.pathname === "/" && location.hash === href.slice(hashIndex);
  };

  const toggleDarkMode = (e) => {
    e.preventDefault();
    setIsDarkMode(!isDarkMode);
  };

  useEffect(() => {
    const body = document.body;
    if (isDarkMode) {
      body.classList.add('odd');
    } else {
      body.classList.remove('odd');
    }
  }, [isDarkMode]);

  return (
    <header id="header">
      <nav className="navbar navbar-expand">
        <div className="container header">
          {/* Navbar Brand */}
          <div className="magnetic">
            <Link className="navbar-brand" to="/">
              {site.brand}
            </Link>
          </div>
          <div className="ms-auto"></div>

          {/* Navbar Nav */}
          <ul className="navbar-nav items d-none d-md-block">
            {menuItems.map((item, index) => (
              <li className="nav-item" key={index}>
                <Link
                  to={item.href}
                  onClick={(e) => handleNavClick(e, item.href)}
                  className={`nav-link ${isActive(item.href) ? "active" : ""}`}
                >
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>

          <ul className="navbar-nav icons d-flex align-items-center">
            <li className="nav-item">
              <a
                href="/#"
                className="nav-link"
                onClick={toggleDarkMode}
                aria-label={isDarkMode ? "Change to light theme" : "Change to dark theme"}
              >
                <span className="icon material-symbols-outlined">
                  {isDarkMode ? "light_mode" : "dark_mode"}
                </span>
              </a>
            </li>
          </ul>

          {/* Navbar Toggler */}
          <div
            className="navbar-toggler scrolled"
            data-bs-toggle="offcanvas"
            data-bs-target="#offcanvasRight"
          >
            <div className="navbar-header">
              <div className="content">
                <div className="toggler-icon"></div>
                <span className="title">Menu</span>
              </div>
            </div>
          </div>
        </div>
      </nav>

      <div id="navbar-main" className="main"></div>
    </header>
  );
};

export default Header;
